window.HK_COND={"fetchedAt":"2026-09-26T20:35+08:00","obsTime":"2026-09-26T20:02:00+08:00","warnings":["WFIREY"],"detail_en":["The Fire Danger Warning is Yellow and the fire risk is High."],"detail_zh":["現時之火災危險警告為黃色，表示火災危險性頗高。"],"temps":{"King's Park":28,"Hong Kong Observatory":29,"Wong Chuk Hang":27,"Ta Kwu Ling":27,"Lau Fau Shan":27,"Tai Po":29,"Sha Tin":28,"Tuen Mun":28,"Tseung Kwan O":27,"Sai Kung":28,"Cheung Chau":26,"Chek Lap Kok":29,"Tsing Yi":27,"Shek Kong":28,"Tsuen Wan Ho Koon":26,"Tsuen Wan Shing Mun Valley":28,"Hong Kong Park":28,"Shau Kei Wan":28,"Kowloon City":28,"Happy Valley":28,"Wong Tai Sin":28,"Stanley":28,"Kwun Tong":27,"Sham Shui Po":28,"Kai Tak Runway Park":29,"Yuen Long Park":28,"Tai Mei Tuk":28},"humidity":71,"uv":null,"today_en":"Mainly fine. The minimum temperature will be about 27 degrees tomorrow morning. Very hot and dry during the day with a maximum temperature of around 33 degrees in the urban areas, and a couple of degrees higher in the New Territories. Moderate southwesterly winds.","today_zh":"大致天晴。明早最低氣溫約27度。日間酷熱及乾燥，市區最高氣溫約33度，新界再高一兩度。吹和緩西南風。","outlook_en":"Mainly fine and very hot in the following couple of days. Becoming cloudier gradually with a few showers on the National Day and in the latter part of next week.","outlook_zh":"隨後兩三日大致天晴及酷熱。國慶日及下週後期雲量逐漸增多及有幾陣驟雨。","situation_en":"Under the influence of an anticyclone aloft, the weather will be mainly fine and very hot over southeastern China in the next few days. A surge of northeast monsoon is expected to affect southern China gradually in the latter part of next week. It will become cloudier gradually with a few showers over the region. Besides, Tropical Cyclone Surigae will intensify and move across the seas east of the Ryukyu Islands in the next couple of days. It will then move towards the seas south of Japan.","situation_zh":"受高空反氣旋影響，未來數日中國東南部天色大致良好及酷熱。預料一股東北季候風會在下週後期逐漸影響華南，該區雲量逐漸增多及有幾陣驟雨。此外，熱帶氣旋舒力基會在未來一兩日增強，並橫過琉球群島以東海域，隨後移向日本以南海域。","forecast":[{"date":"20260927","max":33,"min":27,"rhmax":85,"psr":"Low","wx_en":"Mainly fine. Dry and very hot during the day.","wx_zh":"大致天晴。日間酷熱及乾燥。","wind_en":"Southwest force 3 to 4.","wind_zh":"西南風3至4級。"},{"date":"20260928","max":33,"min":28,"rhmax":85,"psr":"Low","wx_en":"Mainly fine. Very hot during the day. Cloudy periods in the morning and at night.","wx_zh":"大致天晴。日間酷熱。早晚部分時間多雲。","wind_en":"Southwest force 3 to 4.","wind_zh":"西南風3至4級。"},{"date":"20260929","max":33,"min":28,"rhmax":90,"psr":"Low","wx_en":"Mainly fine. Very hot during the day. Cloudy periods in the morning and at night.","wx_zh":"大致天晴。日間酷熱。早晚部分時間多雲。","wind_en":"Southwest force 3.","wind_zh":"西南風3級。"}],"cloud":{"obsTime":"2026-09-26T12:30:00.000Z","raw":"METAR VHHH 261230Z VRB03KT 9999 FEW018 29/23 Q1010 NOSIG","layers":[{"cover":"FEW","base_m":549,"frac":0.19}],"temp":29,"dewp":23,"lcl_m":750,"vis":"6+","wdir":"VRB","wspd_kt":3,"hill_temps":{"Chek Lap Kok":28.6,"Ngong Ping":22.0,"Tai Mo Shan":22.8,"The Peak":24.2},"wind_ngongping":["West","8","14"],"peaks":[{"en":"Lantau Peak","zh":"鳳凰山","m":934,"status":"patches"},{"en":"Sunset Peak","zh":"大東山","m":869,"status":"patches"},{"en":"Tai Mo Shan","zh":"大帽山","m":957,"status":"patches"},{"en":"Ma On Shan","zh":"馬鞍山","m":702,"status":"patches"},{"en":"Victoria Peak","zh":"扯旗山","m":552,"status":"patches"},{"en":"Lion Rock","zh":"獅子山","m":495,"status":"clear"}],"taf":[{"from":1790424000,"to":1790470800,"change":null,"prob":null,"clouds":[{"cover":"FEW","base_m":610,"frac":0.19}],"wx":null},{"from":1790445600,"to":1790470800,"change":"TEMPO","prob":null,"clouds":[],"wx":null},{"from":1790470800,"to":1790499600,"change":"BECMG","prob":null,"clouds":[{"cover":"FEW","base_m":610,"frac":0.19}],"wx":null},{"from":1790499600,"to":1790532000,"change":"BECMG","prob":null,"clouds":[{"cover":"FEW","base_m":610,"frac":0.19}],"wx":null}],"source":"Hong Kong International Airport METAR/TAF (VHHH)"},"source":"Hong Kong Observatory open data"};
